package com.example.markdowndesk;
import android.os.Handler;import android.widget.*;import android.graphics.drawable.GradientDrawable;
public final class ProtectedSavesCheck {
 static int checks;static void yes(boolean condition,String why){checks++;if(!condition)throw new AssertionError(why);}
 static ProtectedHarness fixture(int n){ProtectedHarness h=new ProtectedHarness();for(int i=0;i<n;i++)h.inventory.add(new ProtectedHarness.ProtectionStore.Snapshot(i));return h;}
 static void pages(){ProtectedHarness h=fixture(203);h.load();yes(h.store.reads==0&&h.dialog()==null,"asynchronous authoritative read");h.settle();ProtectedHarness.AlertDialog first=h.dialog();yes(first.items.length==100&&first.items[0].startsWith("title-202.md")&&first.items[99].startsWith("title-103.md"),"first sorted hundred");yes(first.getButton(-3)==null,"first no previous");first.getButton(-1).tap();ProtectedHarness.AlertDialog middle=h.dialog();yes(middle.items.length==100&&middle.items[0].startsWith("title-102.md")&&middle.items[99].startsWith("title-3.md"),"middle hundred");middle.getButton(-1).tap();yes(h.dialog().items.length==3&&h.dialog().items[2].startsWith("title-0.md")&&h.dialog().getButton(-1)==null,"last three no next");h.dialog().getButton(-3).tap();yes(h.dialog().items[0].startsWith("title-102.md"),"previous returns middle");h.dialog().item(7);yes(h.launches==0,"selection requires confirmation");h.dialog().getButton(-1).tap();yes(h.launches==1&&"id-95".equals(h.restoreSnapshotId)&&h.pickerRequest==1004&&"title-95.md".equals(h.picker.title)&&h.picker.flags==67,"actual existing new-copy route exact selected ID");yes(h.session()==null,"restore consumes session before launch");ProtectedHarness empty=fixture(0);empty.load();empty.settle();yes(empty.dialog().message.contains("No protected saves")&&empty.dialog().items==null,"empty themed dialog");}
 static void stale(){ProtectedHarness h=fixture(203);h.load();h.load();h.settle();yes(h.store.reads==1,"stale queued load skipped");Object session=h.session();ProtectedHarness.AlertDialog first=h.dialog();first.getButton(-1).tap();ProtectedHarness.AlertDialog second=h.dialog();first.item.clicked(first,0);yes(h.dialog()==second&&h.launches==0,"old row cannot act");first.getButton(-1).tap();yes(h.dialog()==second,"old next cannot replace current");second.item(0);ProtectedHarness.AlertDialog confirmation=h.dialog();confirmation.getButton(-2).tap();yes(h.dialog()!=confirmation,"back returns exact page");confirmation.getButton(-1).tap();yes(h.launches==0,"replaced confirmation cannot restore");h.dialog().item(0);confirmation=h.dialog();confirmation.dismiss();yes(h.session()==null&&h.cleared(session),"dismiss clears list and token");confirmation.getButton(-1).tap();yes(h.launches==0,"dismissed confirmation cannot restore");h.load();h.io.drain();h.pause();Handler.drain();yes(h.session()==null,"pause drops queued delivery");h.load();h.settle();ProtectedHarness.AlertDialog old=h.dialog();h.dirty=true;h.trace.clear();h.pause();yes(h.trace.toString().equals("[capture, recovery, session, cancel]"),"pause queues local save before cancellation");old.item.clicked(old,0);yes(h.session()==null,"paused row inert");h.load();h.io.drain();h.destroy();Handler.drain();yes(h.session()==null,"destroy drops delivery");}
 static void deliveryOwnership(){ProtectedHarness h=fixture(3);h.load();h.io.drain();h.load();Handler.drain();yes(h.dialog()==null,"superseded pending success dropped");h.settle();Object previous=h.session();ProtectedHarness.AlertDialog old=h.dialog();h.load();yes(h.cleared(previous)&&!old.isShowing(),"new request disposes old list immediately");h.settle();old.item.clicked(old,0);yes(h.dialog()!=old&&h.launches==0,"old request row inert");h.dialog().item(0);ProtectedHarness.AlertDialog confirm=h.dialog();h.load();confirm.getButton(-1).tap();yes(h.launches==0,"new request invalidates confirmation");h.settle();h.dialog().dismiss();h.store.failure=new IllegalStateException("storage");h.load();h.io.drain();h.load();Handler.drain();yes(h.error==null,"stale failure cannot present");h.store.failure=null;h.settle();h.finishing=true;ProtectedHarness.AlertDialog live=h.dialog();live.item.clicked(live,0);yes(h.dialog()==live&&h.launches==0,"finishing Activity row inert");h.finishing=false;h.dialog().item(0);h.saveInProgress=true;h.dialog().getButton(-1).tap();yes(h.launches==0&&h.session()==null&&h.error.contains("current save"),"busy existing restore route consumes session and refuses picker");}
 static void themes(){for(int theme=0;theme<9;theme++){ProtectedHarness h=fixture(2);h.palette=UiTheme.palette(theme,false);h.load();h.settle();ProtectedHarness.AlertDialog d=h.dialog();yes(d.customTitle.color==h.palette.text,"actual title palette "+theme);TextView row=(TextView)d.adapter.getView(0,null,null);yes(row.color==h.palette.text,"actual row palette "+theme);row.color=123;yes(d.adapter.getView(1,row,null)==row&&row.color==h.palette.text&&row.text.startsWith("title-0.md"),"recycled row rebound "+theme);yes(((GradientDrawable)d.window.background).color==h.palette.raised,"actual dialog background "+theme);d.item(0);d=h.dialog();yes(d.customTitle.color==h.palette.text&&d.messageView.color==h.palette.text,"actual confirmation text palette "+theme);yes(d.getButton(-1).color==UiTheme.readableForeground(h.palette.accent,h.palette.raised),"actual action palette "+theme);}}
 public static void main(String[] args){pages();stale();deliveryOwnership();themes();System.out.println("Protected saves UI: "+checks+" checks PASS");}
}
